const size = "M";

function pick(label = size, size = "L") {
  return label + size;
}

function attempt(task) {
  try {
    return task();
  } catch (error) {
    return error.name;
  }
}

console.log(attempt(() => pick()));
console.log(attempt(() => pick("S")));
console.log(attempt(() => typeof stock));
